// Primeira porta: so passa adiante uma notificacao de pagamento de verdade.
// A protecao que vale dinheiro nao e esta: e a reconsulta na API do Mercado
// Pago, no proximo no. Esta aqui descarta barulho e, quando ha segredo
// configurado, confere a assinatura.
const req = $input.first().json;
const headers = req.headers ?? {};
const query = req.query ?? {};
const body = req.body ?? {};

const topico = query.topic || query.type || body.type || '';
if (topico && topico !== 'payment') return [];

const paymentId = String(body?.data?.id ?? query['data.id'] ?? query.id ?? '').trim();
if (!paymentId) return [];

let segredo = '';
try { segredo = $env.MP_WEBHOOK_SECRET || ''; } catch (e) { segredo = ''; }

if (segredo) {
  const assinatura = String(headers['x-signature'] ?? '');
  const partes = Object.fromEntries(
    assinatura.split(',').map((p) => p.split('=').map((s) => s.trim())),
  );
  const manifesto =
    'id:' + paymentId +
    ';request-id:' + (headers['x-request-id'] ?? '') +
    ';ts:' + (partes.ts ?? '') + ';';

  let calculada;
  try {
    const chave = await crypto.subtle.importKey(
      'raw',
      new TextEncoder().encode(segredo),
      { name: 'HMAC', hash: 'SHA-256' },
      false,
      ['sign'],
    );
    const buf = await crypto.subtle.sign('HMAC', chave, new TextEncoder().encode(manifesto));
    calculada = [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, '0')).join('');
  } catch (erro) {
    throw new Error(
      'Nao consegui calcular a assinatura neste n8n. Remova MP_WEBHOOK_SECRET para seguir sem a conferencia, ou habilite o crypto no Code node. Detalhe: ' + erro.message,
    );
  }

  if (calculada !== partes.v1) throw new Error('Assinatura do webhook invalida.');
}

return [{ json: { paymentId: paymentId } }];

// O Mercado Pago avisa de varias mudancas de estado. So "approved" e dinheiro.
const p = $input.first().json;
if (p.status !== 'approved') return [];

// payment_type_id -> chave da forma de pagamento no ERP.
const metodos = {
  credit_card: 'credit_card',
  debit_card: 'debit_card',
  ticket: 'boleto',
  bank_transfer: 'pix',
  account_money: 'transfer',
};

// O external_reference foi preenchido pela Leona com o telefone do contato.
const telefone = String(p.external_reference ?? '').replace(/[^0-9]/g, '');
if (!telefone) {
  throw new Error('Pagamento ' + p.id + ' chegou sem telefone no external_reference.');
}

const nome =
  p.metadata?.nome ||
  [p.payer?.first_name, p.payer?.last_name].filter(Boolean).join(' ').trim() ||
  'Cliente do WhatsApp';

return [{
  json: {
    paymentId: String(p.id),
    telefone: telefone,
    nome: nome,
    valor: Number(p.transaction_amount).toFixed(2),
    metodo: metodos[p.payment_type_id] ?? null,
    aprovadoEm: p.date_approved ?? null,
  },
}];

// Aqui mora a garantia de nao mandar a mensagem duas vezes.
// Duas redes, nao uma: o cabecalho Idempotency-Key devolve a resposta guardada
// do primeiro envio, e o indice unico (provedor, id externo) do ERP responde
// 409 se o reenvio vier com outra chave. Qualquer um dos dois significa
// "ja tratamos esse pagamento", e o fluxo para aqui sem avisar a Leona.
const res = $input.first().json;
const status = res.statusCode ?? 0;
const corpo = res.body ?? {};

if (corpo?.meta?.idempotent === true) return [];
if (status === 409) return [];

if (status >= 400) {
  throw new Error('O ERP recusou o lancamento: ' + JSON.stringify(corpo));
}

return [{ json: { transacao: corpo?.data ?? null } }];
